120: if ($Task -notmatch '^[A-Za-z0-9][A-Za-z0-9._-]*$') {
121:     Stop-WithError "-Task must be a slug (letters, digits, dot, dash, underscore)."
122: }
123: if ($Id -or $Status) {
124:     if (-not $Id) { Stop-WithError "-Status needs -Id <finding id>." }
125:     if (-not $Status) { Stop-WithError "-Id needs -Status <$($script:FindingStatuses -join '|')>." }
126:     $Status = $Status.Trim().ToLowerInvariant()
127:     if ($script:FindingStatuses -notcontains $Status) {
128:         Stop-WithError "-Status must be one of: $($script:FindingStatuses -join ', ') (got '$Status')."
129:     }
130:     if ($Status -eq 'verified' -and -not $Evidence.Trim()) {
131:         Stop-WithError "-Status verified requires -Evidence (what was run, or where the proof is)."
132:     }
133:     if ($Status -eq 'rejected' -and -not $Note.Trim()) {
134:         Stop-WithError "-Status rejected requires -Note (why the finding is rejected)."
135:     }
136: }
