138: # ----------------------------------------------------------------------------- paths
139: 
140: $callerCwd = (Get-Location).Path
141: $repoRoot = Resolve-RepoRoot -Cwd $callerCwd
142: $collabRoot = Resolve-CollabRoot -RepoRoot $repoRoot -CollabDir $CollabDir
143: $taskDir = Join-Path $collabRoot $Task
144: $findingsPath = Join-Path $taskDir 'findings.json'
145: $sessionsPath = Join-Path $taskDir 'sessions.json'
146: $pendingPath = Get-PendingPath -TaskDir $taskDir
147: 
148: # One line per interrupted consultation (every recovery record of the task: the single
149: # run's .consult.pending.json and a panel's .consult.pending-<NN>.json), for -List / -Stats
150: # (no lock taken).
151: function Write-PendingLine {
152:     foreach ($path in (Get-PendingPaths -TaskDir $taskDir)) {
153:         $p = Read-PendingFile -Path $path
154:         if (-not $p.Exists) { continue }
155:         if ($p.Error) { Write-Host "pending: $($p.Error)" -ForegroundColor Yellow; continue }
156:         $r = $p.Record
157:         $line = ("pending: state={0}, n={1}, nn={2}, reply={3}, started {4} - an interrupted consultation; the next consultation consumes it ({5})" -f `
158:                 (Get-PropertyValue $r 'state' '?'), (Get-PropertyValue $r 'n' '?'), (Get-PropertyValue $r 'nn' '?'), (Get-PropertyValue $r 'reply' '?'), (Get-PropertyValue $r 'started' '?'), $path)
159:         # stopped during a format-repair turn: the prose it had saved (and the like)
160:         $originalNote = Get-PendingOriginalNote $r
161:         if ($originalNote) { $line += "; $originalNote" }
162:         Write-Host $line -ForegroundColor Yellow
163:     }
164: }
