166: function Read-Ledger {
167:     $data = Read-JsonStore -Path $sessionsPath
168:     if ($null -eq $data -or -not $data.PSObject.Properties['codex'] -or -not $data.codex.PSObject.Properties['consults']) { return @() }
169:     return @($data.codex.consults | Where-Object { $_ })
170: }
171: 
172: # Consult numbers named by a finding's reviewer checks that have no ledger entry
173: # (a consultation that recorded checks and stopped before its ledger write).
174: function Get-OrphanCheckConsults {
175:     param($Finding, [hashtable]$LedgerNs)
176:     $out = New-Object System.Collections.Generic.List[int]
177:     foreach ($rc in @(Get-PropertyValue $Finding 'reviewer_checks' @())) {
178:         $v = 0
179:         if ($rc -and [int]::TryParse([string](Get-PropertyValue $rc 'consult' ''), [ref]$v) -and -not $LedgerNs.ContainsKey($v) -and -not $out.Contains($v)) { $out.Add($v) }
180:     }
181:     return , ([int[]]$out.ToArray())
182: }
183: 
184: function Get-FindingConsult {
185:     param($Finding)
186:     $src = Get-PropertyValue $Finding 'source' $null
187:     if (-not $src) { return $null }
188:     $v = 0
189:     if ([int]::TryParse([string](Get-PropertyValue $src 'consult' ''), [ref]$v)) { return $v }
190:     return $null
191: }
192: 
193: function ConvertTo-ComparablePath {
194:     param([string]$Path)
195:     return ($Path -replace '\\', '/').ToLowerInvariant()
196: }
197: 
198: # ----------------------------------------------------------------------------- -List
199: 
200: if ($List) {
201:     if (-not (Test-Path -LiteralPath $findingsPath)) {
202:         Write-Host "codex-findings: no findings recorded for task '$Task' ($findingsPath does not exist)."
203:         Write-PendingLine
204:         exit 0
205:     }
206:     $store = Read-FindingsFile -Path $findingsPath -Task $Task
207:     $ledger = @(Read-Ledger)
208:     # consult n -> reply path of its ledger entry
209:     $ledgerReplies = @{}
210:     foreach ($c in $ledger) {
211:         $v = 0
212:         if ($c.PSObject.Properties['n'] -and [int]::TryParse([string]$c.n, [ref]$v)) {
213:             $ledgerReplies[$v] = [string](Get-PropertyValue $c 'reply' '')
214:         }
215:     }
216:     $findings = @($store.findings)
217:     $ledgerNs = @{}
218:     foreach ($k in $ledgerReplies.Keys) { $ledgerNs[$k] = $true }
219:     $shown = 0
220:     $orphans = 0
221:     $orphanChecks = 0
222:     $byStatus = [ordered]@{}
223:     foreach ($s in $script:FindingStatuses) { $byStatus[$s] = 0 }
224:     $other = 0
225:     foreach ($f in $findings) {
226:         $st = [string](Get-PropertyValue $f 'status' '')
227:         if ($byStatus.Contains($st)) { $byStatus[$st] = $byStatus[$st] + 1 } else { $other++ }
228:         $n = Get-FindingConsult $f
229:         $srcReply = [string](Get-PropertyValue (Get-PropertyValue $f 'source' $null) 'reply' '')
230:         $orphan = $true
231:         if ($null -ne $n -and $ledgerReplies.ContainsKey($n)) {
232:             $ledgerReply = $ledgerReplies[$n]
233:             $orphan = ($srcReply -and $ledgerReply -and (ConvertTo-ComparablePath $srcReply) -ne (ConvertTo-ComparablePath $ledgerReply))
234:         }
235:         if ($orphan) { $orphans++ }
236:         $badChecks = Get-OrphanCheckConsults -Finding $f -LedgerNs $ledgerNs
237:         $orphanChecks += $badChecks.Count
238:         if (-not $All -and $script:OpenStatuses -notcontains $st -and $badChecks.Count -eq 0) { continue }
239:         $line = Format-FindingLine -Finding $f -Orphan:$orphan
240:         if ($badChecks.Count -gt 0) { $line += "  [ORPHAN reviewer check: consult $($badChecks -join ', ') has no ledger entry]" }
241:         Write-Host $line
242:         $shown++
243:     }
244:     $parts = @(foreach ($k in $byStatus.Keys) { "$k $($byStatus[$k])" })
245:     if ($other -gt 0) { $parts += "other $other" }
246:     $scope = if ($All) { 'all' } else { 'open only, plus any with an orphan check; -All for every finding' }
247:     Write-Host ""
248:     Write-Host "codex-findings: $shown shown ($scope); total $($findings.Count): $($parts -join ', '); orphans: $orphans finding(s), $orphanChecks reviewer check(s)."
249:     Write-PendingLine
250:     exit 0
251: }
252: 
253: # ----------------------------------------------------------------------------- -Stats
254: 
255: if ($Stats) {
256:     $ledger = @(Read-Ledger)
257:     $findings = @()
258:     $findingsStoreForBoard = $null
259:     if (Test-Path -LiteralPath $findingsPath) {
260:         $findingsStoreForBoard = Read-FindingsFile -Path $findingsPath -Task $Task
261:         $findings = @($findingsStoreForBoard.findings)
262:     }
263:     if ($ledger.Count -eq 0) {
264:         Write-Host "codex-findings: no consultations recorded for task '$Task' ($sessionsPath)."
265:         Write-PendingLine
266:         exit 0
267:     }
268:     $fmt = '{0,4}  {1,-13}  {2,-6}  {3,7}  {4,11}  {5,-7}  {6}'
269:     Write-Host ($fmt -f 'n', 'purpose', 'effort', 'wall_s', 'tokens(out)', 'verdict', 'findings: proposed/implemented/verified/rejected')
270:     $seen = @{}
271:     foreach ($c in $ledger) {
272:         $n = $null
273:         $v = 0
274:         if ($c.PSObject.Properties['n'] -and [int]::TryParse([string]$c.n, [ref]$v)) { $n = $v }
275:         $mine = @($findings | Where-Object { $null -ne $n -and (Get-FindingConsult $_) -eq $n })
276:         if ($null -ne $n) { $seen[$n] = $true }
277:         $cnt = @{}
278:         foreach ($s in @('proposed', 'implemented', 'verified', 'rejected')) {
279:             $cnt[$s] = @($mine | Where-Object { [string](Get-PropertyValue $_ 'status' '') -eq $s }).Count
280:         }
281:         $purpose = [string](Get-PropertyValue $c 'purpose' '')
282:         if (-not $purpose) { $purpose = '-' }
283:         $effort = [string](Get-PropertyValue $c 'effort' '-')
284:         $wall = [string](Get-PropertyValue $c 'wall_seconds' '-')
285:         $tokens = '-'
286:         $u = Get-PropertyValue $c 'usage' $null
287:         if ($u -and $null -ne (Get-PropertyValue $u 'output_tokens' $null)) { $tokens = [string]$u.output_tokens }
288:         $verdict = [string](Get-PropertyValue $c 'verdict' '')
289:         if (-not $verdict) {
290:             $verdict = '-'
291:             $outcome = [string](Get-PropertyValue $c 'bridge_outcome' (Get-PropertyValue $c 'outcome' ''))
292:             if ($outcome -like 'failed*') { $verdict = 'failed' }
293:             elseif ([string](Get-PropertyValue $c 'validation_error' '')) { $verdict = 'invalid' }
294:         }
295:         $label = '-'
296:         if ($null -ne $n) { $label = [string]$n }
297:         $findingsText = "$($cnt.proposed)/$($cnt.implemented)/$($cnt.verified)/$($cnt.rejected)"
298:         if ($mine.Count -gt 0) { $findingsText += " ($($mine.Count) total)" }
299:         Write-Host ($fmt -f $label, $purpose, $effort, $wall, $tokens, $verdict, $findingsText)
300:     }
301:     # Per-reviewer scoreboard: every finding counted for the lineage '<provider> :: <model>'
302:     # of the ledger entry it was ingested from (its source.consult = the entry's n). An
303:     # entry without a reviewer object (recorded before 0.3.0), or a finding whose consult
304:     # has no ledger entry, is 'unknown provenance'. Lineages in ledger order, one line each
305:     # (also a reviewer that raised nothing), unknown provenance last.
306:     $lineageOf = @{}
307:     $lineageOrder = New-Object System.Collections.Generic.List[string]
308:     foreach ($c in $ledger) {
309:         $v = 0
310:         if (-not ($c.PSObject.Properties['n'] -and [int]::TryParse([string]$c.n, [ref]$v))) { continue }
311:         $rev = Get-PropertyValue $c 'reviewer' $null
312:         $label = 'unknown provenance'
313:         if ($null -ne $rev) { $label = Format-ReviewerLineage -Provider ([string](Get-PropertyValue $rev 'provider' '')) -Model ([string](Get-PropertyValue $rev 'model' '')) -Engine ([string](Get-PropertyValue $rev 'engine' '')) }
314:         $lineageOf[$v] = $label
315:         if ($label -ne 'unknown provenance' -and -not $lineageOrder.Contains($label)) { $lineageOrder.Add($label) }
316:     }
317:     $board = @{}
318:     foreach ($f in $findings) {
319:         $fn = Get-FindingConsult $f
320:         $label = 'unknown provenance'
321:         if ($null -ne $fn -and $lineageOf.ContainsKey($fn)) { $label = $lineageOf[$fn] }
322:         if (-not $board.ContainsKey($label)) { $board[$label] = New-Object System.Collections.Generic.List[object] }
323:         $board[$label].Add($f)
324:     }
325:     if ($board.ContainsKey('unknown provenance')) { $lineageOrder.Add('unknown provenance') }
326:     if ($lineageOrder.Count -gt 0) {
327:         $wName = [Math]::Max(8, (@($lineageOrder | ForEach-Object { $_.Length }) | Measure-Object -Maximum).Maximum)
328:         $boardFmt = '{0,-' + $wName + '}  {1,6}  {2,8}  {3,11}  {4,8}  {5,8}  {6,7}  {7,10}  {8,3}  {9,6}  {10,2}'
329:         # The judge's marks (-Rate), counted for the lineage recorded with each mark.
330:         $marks = @{}
331:         foreach ($mk in @(Get-PropertyValue $findingsStoreForBoard 'ratings' @())) {
332:             if ($null -eq $mk) { continue }
333:             $ml = [string](Get-PropertyValue $mk 'lineage' 'unknown provenance')
334:             if (-not $marks.ContainsKey($ml)) { $marks[$ml] = @{ yes = 0; partly = 0; no = 0 } }
335:             $mu = [string](Get-PropertyValue $mk 'useful' '')
336:             if ($marks[$ml].ContainsKey($mu)) { $marks[$ml][$mu]++ }
337:         }
338:         Write-Host ""
339:         Write-Host "reviewers (findings by the lineage of the consultation that raised them; ratings = the judge's marks, -Rate):"
340:         Write-Host ($boardFmt -f 'reviewer', 'raised', 'verified', 'implemented', 'proposed', 'rejected', 'wontfix', 'superseded', 'yes', 'partly', 'no')
341:         foreach ($label in $lineageOrder) {
342:             $mineB = @()
343:             if ($board.ContainsKey($label)) { $mineB = @($board[$label].ToArray()) }
344:             $cntB = @{}
345:             foreach ($s in $script:FindingStatuses) { $cntB[$s] = @($mineB | Where-Object { [string](Get-PropertyValue $_ 'status' '') -eq $s }).Count }
346:             $mkB = if ($marks.ContainsKey($label)) { $marks[$label] } else { @{ yes = 0; partly = 0; no = 0 } }
347:             Write-Host ($boardFmt -f $label, $mineB.Count, $cntB['verified'], $cntB['implemented'], $cntB['proposed'], $cntB['rejected'], $cntB['wontfix'], $cntB['superseded'], $mkB['yes'], $mkB['partly'], $mkB['no'])
348:         }
349:     }
350:     $orphanCount = @($findings | Where-Object { $n = Get-FindingConsult $_; $null -eq $n -or -not $seen.ContainsKey($n) }).Count
351:     $orphanCheckCount = 0
352:     foreach ($f in $findings) { $orphanCheckCount += (Get-OrphanCheckConsults -Finding $f -LedgerNs $seen).Count }
353:     if ($orphanCount -gt 0 -or $orphanCheckCount -gt 0) {
354:         Write-Host ""
355:         Write-Host "codex-findings: $orphanCount finding(s) and $orphanCheckCount reviewer check(s) belong to no ledger entry (ORPHAN; see -List -All)." -ForegroundColor Yellow
356:     }
357:     Write-PendingLine
358:     exit 0
359: }
360: 
361: # ----------------------------------------------------------------------------- -Rate
362: 
363: if ($rating) {
364:     if (-not (Test-Path -LiteralPath $sessionsPath -PathType Leaf)) {
365:         Stop-WithError "no consultations recorded for task '$Task' ($sessionsPath does not exist); -Rate takes the n of a ledger entry."
366:     }
367:     $lock = Enter-TaskLock -TaskDir $taskDir -Task $Task
368:     if (-not $lock.Acquired) { Stop-WithError $lock.Message }
369:     $commit = $null
370:     try {
371:         # The store commit (write lock, both stores re-read under it): the mark goes into the
372:         # FRESH findings.json.
373:         $commit = Enter-StoreCommit -TaskDir $taskDir -Task $Task -TimeoutSec (Get-WriteLockTimeout)
374:         if (-not $commit.Acquired) { Stop-WithError "$($commit.Message); nothing was changed." }
375:         $entry = $null
376:         $ledgerData = $commit.Sessions
377:         $ledgerConsults = @()
378:         if ($null -ne $ledgerData -and $ledgerData.PSObject.Properties['codex'] -and $ledgerData.codex.PSObject.Properties['consults']) { $ledgerConsults = @($ledgerData.codex.consults | Where-Object { $_ }) }
379:         foreach ($c in $ledgerConsults) {
380:             $v = 0
381:             if ($c.PSObject.Properties['n'] -and [int]::TryParse([string]$c.n, [ref]$v) -and $v -eq $Rate) { $entry = $c }
382:         }
383:         if (-not $entry) {
384:             Stop-WithError "no consultation n=$Rate in $sessionsPath; -Rate takes the n of a ledger entry (see -Stats)."
385:         }
386:         $rev = Get-PropertyValue $entry 'reviewer' $null
387:         $provider = ''
388:         $model = [string](Get-PropertyValue $entry 'model' '')
389:         $lineage = 'unknown provenance'
390:         if ($null -ne $rev) {
391:             $provider = [string](Get-PropertyValue $rev 'provider' '')
392:             $model = [string](Get-PropertyValue $rev 'model' '')
393:             $lineage = Format-ReviewerLineage -Provider $provider -Model $model -Engine ([string](Get-PropertyValue $rev 'engine' ''))
394:         }
395:         $mark = [pscustomobject]@{
396:             n          = $Rate
397:             consult_id = [string](Get-PropertyValue $entry 'consult_id' '')
398:             lineage    = $lineage
399:             provider   = $provider
400:             model      = $model
401:             purpose    = [string](Get-PropertyValue $entry 'purpose' '')
402:             useful     = $Useful
403:             note       = $Note.Trim()
404:             when       = (Get-IsoTimestamp)
405:         }
406:         # (created on the first mark; a findings.json that exists but does not parse is refused)
407:         $store = $commit.Findings
408:         $kept = New-Object System.Collections.Generic.List[object]
409:         $previous = ''
410:         $replaced = $false
411:         foreach ($old in @(Get-PropertyValue $store 'ratings' @())) {
412:             if ($null -eq $old) { continue }
413:             if ([string](Get-PropertyValue $old 'n' '') -eq [string]$Rate) {
414:                 if (-not $replaced) { $kept.Add($mark); $replaced = $true; $previous = [string](Get-PropertyValue $old 'useful' '') }
415:                 continue
416:             }
417:             $kept.Add($old)
418:         }
419:         if (-not $replaced) { $kept.Add($mark) }
420:         if ($store.PSObject.Properties['ratings']) { $store.ratings = [object[]]$kept.ToArray() }
421:         else { $store | Add-Member -NotePropertyName 'ratings' -NotePropertyValue ([object[]]$kept.ToArray()) }
422:         Complete-StoreCommit -Commit $commit -Findings
423:         Exit-StoreCommit -Commit $commit
424:         $purposeText = if ($mark.purpose) { $mark.purpose } else { 'no purpose' }
425:         if ($replaced) { Write-Host "codex-findings: consult n=$Rate ($lineage, $purposeText) re-rated $Useful (was $previous)." }
426:         else { Write-Host "codex-findings: consult n=$Rate ($lineage, $purposeText) rated $Useful." }
427:         exit 0
428:     } finally {
429:         Exit-StoreCommit -Commit $commit
430:         Exit-TaskLock -Lock $lock
431:     }
432: }
433: 
434: # ----------------------------------------------------------------------------- -Id -Status
435: 
436: if (-not (Test-Path -LiteralPath $findingsPath)) {
437:     Stop-WithError "no findings recorded for task '$Task' ($findingsPath does not exist)."
438: }
439: 
440: $lock = Enter-TaskLock -TaskDir $taskDir -Task $Task
441: if (-not $lock.Acquired) { Stop-WithError $lock.Message }
442: $commit = $null
443: try {
444:     # The recovery records of interrupted consultations are read only to refuse while
445:     # their bridge or codex process may still be running; they are never modified or
446:     # deleted here (the next consultation consumes them).
447:     $pendingAll = Read-TaskPendingRecords -TaskDir $taskDir
448:     if ($pendingAll.Error) { Stop-WithError $pendingAll.Error }
449:     if ($pendingAll.Active) { Stop-WithError $pendingAll.Active.Check.Message }
450: 
451:     # The store commit (write lock, findings.json re-read under it): the change goes into
452:     # the FRESH store.
453:     $commit = Enter-StoreCommit -TaskDir $taskDir -Task $Task -TimeoutSec (Get-WriteLockTimeout) -NoSessions
454:     if (-not $commit.Acquired) { Stop-WithError "$($commit.Message); nothing was changed." }
455:     $store = $commit.Findings
456:     $target = $null
457:     foreach ($f in @($store.findings)) {
458:         if ([string](Get-PropertyValue $f 'id' '') -eq $Id.Trim()) { $target = $f; break }
459:     }
460:     if (-not $target) {
461:         Stop-WithError "unknown finding id '$Id' in $findingsPath (codex-findings.ps1 -Task $Task -List -All shows every id)."
462:     }
463:     $current = [string](Get-PropertyValue $target 'status' '')
464:     if ($Status -eq 'proposed' -and $current -ne 'proposed' -and -not $Note.Trim()) {
465:         Stop-WithError "reopening $($target.id) ($current -> proposed) requires -Note (why it is open again)."
466:     }
467: 
468:     $rev = Get-RevisionInfo -Root $repoRoot -CollabRoot $collabRoot
469:     $record = [pscustomobject]@{
470:         when        = (Get-IsoTimestamp)
471:         status      = $Status
472:         by          = 'coordinator'
473:         note        = $Note.Trim()
474:         evidence    = $Evidence.Trim()
475:         base_commit = $rev.base_commit
476:         tree_sha256 = $rev.tree_sha256
477:     }
478:     Add-ArrayItem -Object $target -Name 'history' -Item $record
479:     if ($target.PSObject.Properties['status']) { $target.status = $Status }
480:     else { $target | Add-Member -NotePropertyName 'status' -NotePropertyValue $Status }
481:     Complete-StoreCommit -Commit $commit -Findings
482:     Exit-StoreCommit -Commit $commit
483: 
484:     Write-Host "codex-findings: $($target.id) $current -> $Status (history: $(@($target.history).Count) records; tree sha256 $(if ($rev.tree_sha256) { $rev.tree_sha256.Substring(0, 12) } else { 'none (no git)' }))."
485:     Write-Host (Format-FindingLine -Finding $target)
486:     exit 0
487: } finally {
488:     Exit-StoreCommit -Commit $commit
489:     Exit-TaskLock -Lock $lock
490: }

630: $presetWords = @{1289:         # ------------------------------------------------------------------ console output, records
1290:         foreach ($slot in $panelSlots) {
1291:             if (@('done', 'killed') -notcontains $slot.State) { continue }
1292:             Write-Host ""
1293:             Write-Host "=== panel $panelShort member $($slot.K) of $($panelRunners.Count): $($slot.Pm.Shown) (roster #$($slot.Pm.Entry.Position)) ==="
1294:             foreach ($l in $slot.Lines) { Write-Host $l }
1295:         }
1296:         if (-not $DryRun) {
1297:             # D5: the records of members that never started, and of launched members that are
1298:             # gone with their record still `reserved` (nothing was started under it), go.
1299:             foreach ($slot in $panelSlots) {
1300:                 $rd = Read-PendingFile -Path $slot.RecordPath
1301:                 if (-not $rd.Exists -or $rd.Error) { continue }
1302:                 $st = [string](Get-PropertyValue $rd.Record 'state' '')
1303:                 if ((@('waiting', 'blocked', 'failed-start') -contains $slot.State) -or $st -eq 'reserved') {
1304:                     $rmError = Remove-PendingFile -Path $slot.RecordPath
1305:                     if ($rmError) { $slot.RecordKept = $true; Write-Host "codex-consult: could not remove the unused recovery record $($slot.RecordPath) ($rmError)" -ForegroundColor Yellow }
1306:                 } else {
1307:                     $slot.RecordKept = $true
1308:                     $slot.RecordState = $st
1309:                 }
1310:             }
1311:         }
1312: 
1313:         # ------------------------------------------------------------------ summary
1314:         $rows = New-Object System.Collections.Generic.List[object]
1315:         $allUsable = ($panelRunners.Count -gt 0)
1316:         $panelStarted = @($panelSlots | Where-Object { @('done', 'killed') -contains $_.State }).Count
1317:         foreach ($pm in $panelEntries) {
