4587: function Enter-TaskLock {
4588:     param([string]$TaskDir, [string]$Task, [string]$Panel = '')
4589:     $path = Join-Path $TaskDir '.consult.lock'
4590:     $share = if ($script:OnWindows) { [IO.FileShare]::Read } else { [IO.FileShare]::None }
4591:     $record = [pscustomobject]@{
4592:         pid        = $PID
4593:         start_time = (Get-ProcessStartIso -ProcessId $PID)
4594:         host       = [Environment]::MachineName
4595:         task       = $Task
4596:         started    = (Get-IsoTimestamp)
4597:     }
4598:     if ($Panel) { $record | Add-Member -NotePropertyName 'panel' -NotePropertyValue $Panel }
4599:     $fs = $null
4600:     try {
4601:         $fs = [IO.File]::Open($path, [IO.FileMode]::OpenOrCreate, [IO.FileAccess]::ReadWrite, $share)
4602:     } catch [System.IO.IOException] {
4603:         # The holder may not have replaced its predecessor's informational record
4604:         # yet: re-read briefly and name a pid only when that pid is alive.
4605:         $holder = $null
4606:         for ($attempt = 1; $attempt -le 8; $attempt++) {
4607:             $candidate = Read-LockContent -Path $path
4608:             $cpid = 0
4609:             if ($candidate -and [int]::TryParse([string](Get-PropertyValue $candidate 'pid' ''), [ref]$cpid) -and
4610:                 (Test-PidAlive -ProcessId $cpid -StartTime (ConvertTo-JsonText (Get-PropertyValue $candidate 'start_time' '')))) { $holder = $candidate; break }
4611:             Start-Sleep -Milliseconds 125
4612:         }
4613:         $who = 'a live process'
4614:         if ($holder) {
4615:             $who = "pid $(Get-PropertyValue $holder 'pid' '?') on $(Get-PropertyValue $holder 'host' '?') since $(Get-PropertyValue $holder 'started' '?')"
4616:             $holderPanel = [string](Get-PropertyValue $holder 'panel' '')
4617:             if ($holderPanel) { $who += " (review panel $($holderPanel.Substring(0, [Math]::Min(8, $holderPanel.Length))))" }
4618:         }
4619:         return (New-LockRefusal -Path $path -Message "another consultation or status update for task '$Task' is running: $path is held open by $who. Wait for it to finish; the lock is released when that process exits.")
4620:     } catch {
4621:         return (New-LockRefusal -Path $path -Message "could not open the lock '$path': $($_.Exception.Message)")
4622:     }
4623:     # Informational only (who holds it); nothing recoverable lives here.
4624:     try {
4625:         $bytes = $script:Utf8NoBom.GetBytes((ConvertTo-Json -InputObject $record -Compress) + "`n")
4626:         $fs.SetLength(0)
4627:         $fs.Position = 0
4628:         $fs.Write($bytes, 0, $bytes.Length)
4629:         $fs.Flush($true)
4630:     } catch { }
4631:     return [pscustomobject]@{ Acquired = $true; Path = $path; Stream = $fs; Record = $record; Message = '' }
4632: }
