4707: # THE way every writer changes a task's stores (D2, F04-3): codex-consult.ps1 (a single run,
4708: # a panel member) and codex-findings.ps1 (-Status, -Rate). Takes the write lock, then
4709: # RE-READS findings.json and sessions.json; the caller applies ITS OWN delta to these fresh
4710: # objects, writes them with Complete-StoreCommit (findings.json, then sessions.json) and
4711: # releases with Exit-StoreCommit in a finally. A store that no longer parses refuses
4712: # (Read-JsonStore; the lock is released on the way out). Not acquired within $TimeoutSec:
4713: # Acquired $false and the Message - the caller gives up WITHOUT touching the stores (D3).
4714: # { Acquired; Message; Waited; Lock; FindingsPath; SessionsPath; Findings (the fresh store,
4715: # a new one when absent); Sessions (the fresh ledger object, $null when absent) }.
4716: function Enter-StoreCommit {
4717:     param([string]$TaskDir, [string]$Task, [double]$TimeoutSec = 60, [switch]$NoSessions)
4718:     $lock = Enter-WriteLock -TaskDir $TaskDir -Task $Task -TimeoutSec $TimeoutSec
4719:     $c = [pscustomobject]@{
4720:         Acquired     = [bool]$lock.Acquired
4721:         Message      = [string]$lock.Message
4722:         Waited       = $lock.Waited
4723:         Lock         = $lock
4724:         FindingsPath = (Join-Path $TaskDir 'findings.json')
4725:         SessionsPath = (Join-Path $TaskDir 'sessions.json')
4726:         Findings     = $null
4727:         Sessions     = $null
4728:     }
4729:     if (-not $c.Acquired) { return $c }
4730:     $read = $false
4731:     try {
4732:         $c.Findings = Read-FindingsFile -Path $c.FindingsPath -Task $Task
4733:         if (-not $NoSessions) { $c.Sessions = Read-JsonStore -Path $c.SessionsPath }
4734:         $read = $true
4735:     } finally {
4736:         if (-not $read) { Exit-TaskLock -Lock $lock; $c.Acquired = $false }
4737:     }
4738:     return $c
4739: }
