4741: # Writes the commit's fresh stores in the documented order: findings.json, then
4742: # sessions.json (the commit point). Only while the write lock is held.
4743: function Complete-StoreCommit {
4744:     param($Commit, [switch]$Findings, [switch]$Sessions)
4745:     if ($null -eq $Commit -or -not $Commit.Acquired -or -not $Commit.Lock.Acquired) { throw 'Complete-StoreCommit: the write lock is not held' }
4746:     if ($Findings) { Write-FindingsFile -Path $Commit.FindingsPath -Store $Commit.Findings }
4747:     if ($Sessions) { Write-JsonFile -Path $Commit.SessionsPath -Object $Commit.Sessions }
4748: }
