4923: # One process: { pid; name (ProcessName); cmd; start (UTC round-trip, '' when it cannot
4924: # be read) }, or $null when no process has that pid.
4925: function Get-ProcessInfo {
4926:     param([int]$ProcessId)
4927:     if ($ProcessId -le 0) { return $null }
4928:     $p = $null
4929:     try { $p = Get-Process -Id $ProcessId -ErrorAction Stop } catch { return $null }
4930:     $start = ''
4931:     try { $start = $p.StartTime.ToUniversalTime().ToString('o', $script:Invariant) } catch { $start = '' }
4932:     $cmd = ''
4933:     $previous = $ErrorActionPreference
4934:     $ErrorActionPreference = 'Continue'
4935:     try {
4936:         if ($script:OnWindows) {
4937:             try {
4938:                 $w = Get-CimInstance -ClassName Win32_Process -Filter "ProcessId=$ProcessId" -Property CommandLine -ErrorAction Stop
4939:                 if ($w) { $cmd = [string]@($w)[0].CommandLine }
4940:             } catch { $cmd = '' }
4941:         } else {
4942:             try { $cmd = ((@(& ps -o 'args=' -p $ProcessId 2>$null)) -join ' ').Trim() } catch { $cmd = '' }
4943:         }
4944:     } finally { $ErrorActionPreference = $previous }
4945:     return [pscustomobject]@{ pid = $ProcessId; name = [string]$p.ProcessName; cmd = $cmd; start = $start }
