4958: # Is a process recorded in a pending record still that process? Returns { Alive; How }.
4959: #   with a recorded start time: alive only when the pid runs with that start time (and
4960: #     that name, when one is recorded) - a different start time means the pid was
4961: #     reused by an unrelated process;
4962: #   without one (older records), or when the live start time cannot be read: alive
4963: #     only when the process looks like codex (Get-CodexRule) - never by pid alone.
4964: function Test-RecordedProcess {
4965:     param([int]$ProcessId, [string]$StartTime = '', [string]$Name = '', [string]$Launcher = '')
4966:     $info = Get-ProcessInfo -ProcessId $ProcessId
4967:     if (-not $info) { return [pscustomobject]@{ Alive = $false; How = 'gone' } }
4968:     if ($StartTime -and $info.start) {
4969:         if (-not (Test-SameStartTime -A $info.start -B $StartTime)) { return [pscustomobject]@{ Alive = $false; How = 'pid reused (start time differs)' } }
4970:         if ($Name -and -not $info.name.Equals($Name, [StringComparison]::OrdinalIgnoreCase)) { return [pscustomobject]@{ Alive = $false; How = "pid reused (now $($info.name))" } }
4971:         return [pscustomobject]@{ Alive = $true; How = 'pid + start time' }
4972:     }
4973:     $rule = Get-CodexRule -Name $info.name -Cmd $info.cmd -Launcher $Launcher
4974:     if ($rule) { return [pscustomobject]@{ Alive = $true; How = "no start time recorded; $rule" } }
4975:     return [pscustomobject]@{ Alive = $false; How = "no start time recorded; pid $ProcessId runs $($info.name), not codex" }
4976: }
