602: # The paths whose manifest lines (Get-RevisionInfo .manifest) differ between two
603: # fingerprints: a file that appeared, disappeared or changed (content, mode, status), in
604: # manifest order, each once. The agy engine's tree check names them (A17).
605: function Get-ManifestChanges {
606:     param([string]$Before, [string]$After)
607:     $b = @{}
608:     $a = @{}
609:     foreach ($l in @(([string]$Before) -split "`n")) { if ($l -and -not $l.StartsWith('base ')) { $b[$l] = $true } }
610:     foreach ($l in @(([string]$After) -split "`n")) { if ($l -and -not $l.StartsWith('base ')) { $a[$l] = $true } }
611:     $paths = New-Object System.Collections.Generic.List[string]
612:     foreach ($l in @($b.Keys) + @($a.Keys)) {
613:         if ($b.ContainsKey($l) -and $a.ContainsKey($l)) { continue }
614:         # "XY mode blob path[<TAB>orig]"
615:         $parts = $l.Split(' ', 4)
616:         $p = if ($parts.Count -ge 4) { $parts[3].Split("`t")[0] } else { $l }
617:         if (-not $paths.Contains($p)) { $paths.Add($p) }
618:     }
