624: # Relative path ('/'-separated) -> "<length>|<sha256>" of EVERY file under $Dir, recursively
625: # (0.4.0 wave 18: the whole collab root - every task's stores findings.json / sessions.json /
626: # state.md and handoffs - which lies outside the tree fingerprint). Left out: the bridge's
627: # own lock and recovery files (a name starting with .consult., and the atomic-write temp
628: # ..consult.*), .git directories, and directories that are reparse points (a junction or a
629: # symlink is not followed). An absent directory is an empty snapshot.
630: function Get-CollabSnapshot {
631:     param([string]$Dir)
632:     # ordinal keys: a.md and A.md are two files on a case-sensitive filesystem
633:     $snap = New-Object System.Collections.Hashtable ([StringComparer]::Ordinal)
634:     if (-not $Dir -or -not [IO.Directory]::Exists($Dir)) { return $snap }
635:     $root = [IO.Path]::GetFullPath($Dir).TrimEnd([char]'\', [char]'/')
636:     $stack = New-Object System.Collections.Generic.Stack[string]
637:     $stack.Push($root)
638:     while ($stack.Count -gt 0) {
639:         $d = $stack.Pop()
640:         $info = New-Object System.IO.DirectoryInfo($d)
641:         $files = @()
642:         $subdirs = @()
643:         try { $files = @($info.GetFiles()); $subdirs = @($info.GetDirectories()) } catch { continue }
644:         foreach ($f in $files) {
645:             if ($f.Name.StartsWith('.consult.', [StringComparison]::OrdinalIgnoreCase) -or $f.Name.StartsWith('..consult.', [StringComparison]::OrdinalIgnoreCase)) { continue }
646:             $rel = $f.FullName.Substring($root.Length).TrimStart([char]'\', [char]'/').Replace('\', '/')
647:             $snap[$rel] = "$($f.Length)|$(Get-FileSha256OrMissing -Path $f.FullName)"
648:         }
649:         foreach ($s in $subdirs) {
650:             if ($s.Name -eq '.git') { continue }
651:             if (($s.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { continue }
652:             $stack.Push($s.FullName)
653:         }
654:     }
655:     return $snap
656: }
