685: # Built artifacts to bind a review to: resolves each path (as given, relative to one
686: # of $Bases or absolute) to { path = as given; full = absolute path }. A missing
687: # artifact stops the run - the caller asked to bind the review to it, silently
688: # skipping it would defeat the binding. Hashing happens separately (under the task
689: # lock, and again after the run). Emits one object per artifact; collect with @(...).
690: function Resolve-ArtifactPaths {
691:     param([string[]]$Paths, [string[]]$Bases)
692:     foreach ($raw in @($Paths)) {
693:         if (-not $raw) { continue }
694:         $resolved = $null
695:         if ([IO.Path]::IsPathRooted($raw)) {
696:             if (Test-Path -LiteralPath $raw -PathType Leaf) { $resolved = $raw }
697:         } else {
698:             foreach ($b in $Bases) {
699:                 $candidate = Join-Path $b $raw
700:                 if (Test-Path -LiteralPath $candidate -PathType Leaf) { $resolved = $candidate; break }
701:             }
