4980: #   Windows, with the interrupted bridge's pid ($BridgePid): a process counts when its
4981: #     ParentProcessId is that pid (any name) - Windows keeps the parent id of an orphan,
4982: #     so this attributes the process to THIS task's run. If a live process now owns
4983: #     that pid (reused), only children created before it started count.
4984: #   otherwise (no bridge pid recorded, or not Windows, where orphans are reparented):
4985: #     the "looks like codex" rule (Get-CodexRule), which cannot tell which task a
4986: #     process belongs to - such matches are labelled "task not verifiable".
4987: # Returns { Found = [object[]] { pid; name; rule }; Check = <what was scanned>; Failed }.
4988: function Find-CodexProcesses {
4989:     param([datetime]$Since, [string]$Launcher = '', [int]$BridgePid = 0)
4990:     $found = New-Object System.Collections.Generic.List[object]
4991:     $sinceText = $Since.ToString('yyyy-MM-ddTHH:mm:ss', $script:Invariant)
4992:     $byParent = ($script:OnWindows -and $BridgePid -gt 0)
4993:     $rules = if ($byParent) { "children of the interrupted bridge pid $BridgePid" } else { 'name codex*, or a command line containing the recorded launcher or @openai/codex' }
4994:     $previous = $ErrorActionPreference
4995:     $ErrorActionPreference = 'Continue'
4996:     try {
4997:         $procs = New-Object System.Collections.Generic.List[object]
4998:         if ($script:OnWindows) {
4999:             $check = "Win32_Process scan ($rules; started at or after $sinceText)"
5000:             $all = $null
5001:             try { $all = @(Get-CimInstance -ClassName Win32_Process -Property ProcessId, ParentProcessId, Name, CommandLine, CreationDate -ErrorAction Stop) } catch {
5002:                 return [pscustomobject]@{ Found = [object[]]@(); Check = "$check could not run: $(ConvertTo-OneLine $_.Exception.Message)"; Failed = $true }
5003:             }
5004:             foreach ($p in $all) {
5005:                 $procs.Add([pscustomobject]@{ pid = [int]$p.ProcessId; ppid = [int]$p.ParentProcessId; name = [string]$p.Name; cmd = [string]$p.CommandLine; created = $p.CreationDate })
5006:             }
5007:         } else {
5008:             $check = "ps scan ($rules; started at or after $sinceText)"
5009:             $lines = $null
5010:             try { $lines = @(& ps -eo 'pid=,ppid=,etimes=,comm=,args=' 2>$null) } catch { $lines = $null }
5011:             if ($LASTEXITCODE -ne 0 -or $null -eq $lines) {
5012:                 return [pscustomobject]@{ Found = [object[]]@(); Check = "$check could not run"; Failed = $true }
5013:             }
5014:             $now = Get-Date
5015:             foreach ($l in $lines) {
5016:                 $m = [regex]::Match([string]$l, '^\s*(\d+)\s+(\d+)\s+(\d+)\s+(\S+)\s*(.*)$')
5017:                 if (-not $m.Success) { continue }
5018:                 $procs.Add([pscustomobject]@{ pid = [int]$m.Groups[1].Value; ppid = [int]$m.Groups[2].Value; name = $m.Groups[4].Value; cmd = $m.Groups[5].Value; created = $now.AddSeconds( - [double]$m.Groups[3].Value) })
5019:             }
5020:         }
5021:         # never count ourselves or our ancestors (the shell that started this run may
5022:         # carry the launcher path on its command line)
5023:         $byId = @{}
5024:         foreach ($p in $procs) { $byId[$p.pid] = $p }
5025:         $excluded = @{}
5026:         $cur = $PID
5027:         for ($guard = 0; $guard -lt 64 -and $cur -gt 0 -and -not $excluded.ContainsKey($cur); $guard++) {
5028:             $excluded[$cur] = $true
5029:             if (-not $byId.ContainsKey($cur)) { break }
5030:             $cur = $byId[$cur].ppid
5031:         }
5032:         if ($byParent) {
5033:             # A live process holding the bridge's pid now is a reuse (the bridge itself
5034:             # is gone - we hold the lock); its children are not ours, ours predate it.
5035:             $reusedAt = $null
5036:             if ($byId.ContainsKey($BridgePid)) { $reusedAt = $byId[$BridgePid].created }
5037:             foreach ($p in $procs) {
5038:                 if ($excluded.ContainsKey($p.pid) -or $p.ppid -ne $BridgePid) { continue }
5039:                 if ($null -eq $p.created -or $p.created -lt $Since) { continue }
5040:                 if ($null -ne $reusedAt -and $p.created -ge $reusedAt) { continue }
5041:                 $found.Add([pscustomobject]@{ pid = $p.pid; name = $p.name; rule = "child of the interrupted bridge (ppid $BridgePid)" })
5042:             }
5043:         } else {
5044:             foreach ($p in $procs) {
5045:                 if ($excluded.ContainsKey($p.pid)) { continue }
5046:                 if ($null -eq $p.created -or $p.created -lt $Since) { continue }
5047:                 $rule = Get-CodexRule -Name $p.name -Cmd $p.cmd -Launcher $Launcher
5048:                 if ($rule) { $found.Add([pscustomobject]@{ pid = $p.pid; name = $p.name; rule = "$rule, task not verifiable" }) }
5049:             }
5050:         }
5051:         return [pscustomobject]@{ Found = [object[]]$found.ToArray(); Check = $check; Failed = $false }
5052:     } finally {
5053:         $ErrorActionPreference = $previous
5054:     }
5055: }
