128:     try {
129:         $fs.Write($bytes, 0, $bytes.Length)
130:         $fs.Flush($true)
131:     } finally { $fs.Dispose() }
132:     $lastError = $null
133:     for ($attempt = 1; $attempt -le 8; $attempt++) {
134:         try {
