521: # One more turn of a non-codex engine (the denial retry, the format repair) under the SAME
522: # task lock and recovery record as the run: the record goes launching -> running (child pid,
523: # start time, `events` = this turn's event stream) before the process is waited on; a timeout
524: # kills the process tree, and survivors are recorded (state survivors) and keep the record.
525: # Reads the run's $pendingRecord, $pendingPath, $engineLauncher, $engineName and $repoRoot.
526: # { Exit (-1 unless it exited); Problem ('' or why the turn did not complete); Wall;
527: # KeepPending; Stderr (UTF-8 text) }.
528: function Invoke-EngineTurn {
529:     param([string[]]$Argv, [string]$StdinText, [string]$EventsPath, [string]$StdinPath, [string]$StderrPath, [int]$Timeout, [string]$Note)
530:     $t = [pscustomobject]@{ Exit = -1; Problem = ''; Wall = 0; KeepPending = $false; Stderr = '' }
531:     Write-Utf8NoBom -Path $StdinPath -Text $StdinText
532:     $watch = [System.Diagnostics.Stopwatch]::StartNew()
533:     $pendingRecord.state = 'launching'
534:     $pendingRecord.note = "$Note being started; its pid is not recorded yet"
535:     try { Write-PendingFile -Path $pendingPath -Record $pendingRecord } catch {
536:         $t.Problem = "could not write the recovery record ($(ConvertTo-OneLine $_.Exception.Message)); the turn was not started"
537:         return $t
538:     }
539:     $proc = $null
540:     try {
541:         $proc = Start-Process -FilePath $engineLauncher -ArgumentList ((($Argv | ForEach-Object { ConvertTo-ProcArg $_ }) -join ' ')) `
542:             -WorkingDirectory $repoRoot -NoNewWindow -PassThru `
543:             -RedirectStandardOutput $EventsPath `
544:             -RedirectStandardError $StderrPath `
545:             -RedirectStandardInput $StdinPath
546:     } catch {
547:         $t.Problem = "could not start $engineName - $(ConvertTo-OneLine $_.Exception.Message)"
548:     }
549:     if ($proc) {
550:         if ($script:LegacyPS) { try { $null = $proc.Handle } catch { } }
551:         $registered = $true
552:         try {
553:             $pendingRecord.state = 'running'
554:             $pendingRecord.child_pid = $proc.Id
555:             $pendingRecord.child_start_time = [string](Get-ProcessStartIso -ProcessId $proc.Id)
556:             $pendingRecord.note = $Note
557:             $evRel = Get-RepoRelativePath -Root $repoRoot -Path $EventsPath
558:             $pendingRecord.events = $(if ($evRel) { $evRel } else { $EventsPath })
559:             Write-PendingFile -Path $pendingPath -Record $pendingRecord
560:         } catch {
561:             $registered = $false
562:             $t.Problem = "could not register the $Note process ($(ConvertTo-OneLine $_.Exception.Message)); it was stopped"
563:             # the record on disk still says launching: so does the one in memory
564:             $pendingRecord.state = 'launching'; $pendingRecord.child_pid = $null; $pendingRecord.child_start_time = ''
565:             $null = Stop-ProcessTree -Process $proc
566:         }
567:         if ($registered) {
568:             if (-not $proc.WaitForExit($Timeout * 1000)) {
569:                 $surv = Stop-ProcessTree -Process $proc   # [int[]]; never wrap in @()
570:                 $t.Problem = "timeout after $Timeout s (process tree killed)"
571:                 if ($surv.Count -gt 0) {
572:                     $t.Problem = "timeout after $Timeout s (process tree killed; $($surv.Count) processes survived: pid $($surv -join ', '))"
573:                     $t.KeepPending = $true
574:                     try {
575:                         $pendingRecord.state = 'survivors'
576:                         $pendingRecord.survivors = [object[]]@(New-SurvivorEntries -Pids $surv)
577:                         Write-PendingFile -Path $pendingPath -Record $pendingRecord
578:                     } catch { }
579:                 }
580:             } else {
581:                 $t.Exit = $proc.ExitCode
582:             }
583:         }
584:     }
585:     $watch.Stop()

